  };
}

export function toInvitation(row: InvitationRow): Invitation {

/**
 * Out-of-office rows. One per member per workspace; every query is org-scoped.
 */
import { and, eq } from "drizzle-orm";
import { getDb, memberAbsences } from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { orgPredicate } from "./base-repository";
import { toMemberAbsence } from "./_mappers";
import type { IsoTimestamp, OrgId, UserId } from "@/types/common";
import type { MemberAbsence } from "@/types/member";

export interface AbsenceWrite {
  readonly orgId: OrgId;
  readonly userId: UserId;
  readonly delegateUserId: UserId | null;
  readonly startsAt: IsoTimestamp;
  readonly endsAt: IsoTimestamp;
  readonly note: string | null;
}

export async function findAbsence(
  orgId: OrgId,
  userId: UserId,
): Promise<MemberAbsence | null> {
  const row = getDb()
    .select()
    .from(memberAbsences)
    .where(
      and(
        orgPredicate(memberAbsences.orgId, orgId),
        eq(memberAbsences.userId, userId),
      ),
    )
    .get();
  return row ? toMemberAbsence(row) : null;
}

/** Insert or replace the member's single absence in this workspace. */
export async function upsertAbsence(input: AbsenceWrite): Promise<MemberAbsence> {
  const stamp = toIsoTimestamp(new Date());
  const row = getDb()
    .insert(memberAbsences)
    .values({
      orgId: input.orgId,
      userId: input.userId,
      delegateUserId: input.delegateUserId,
      startsAt: input.startsAt,
      endsAt: input.endsAt,
      note: input.note,
      createdAt: stamp,
      updatedAt: stamp,
    })
    .onConflictDoUpdate({
      target: [memberAbsences.orgId, memberAbsences.userId],
      set: {
        delegateUserId: input.delegateUserId,
        startsAt: input.startsAt,
        endsAt: input.endsAt,
        note: input.note,
        updatedAt: stamp,
      },
    })
    .returning()
    .get();

  return toMemberAbsence(row);
}

/** Clearing an absence that was never set is a no-op. */
export async function deleteAbsence(orgId: OrgId, userId: UserId): Promise<void> {
  getDb()
    .delete(memberAbsences)
    .where(
      and(
        orgPredicate(memberAbsences.orgId, orgId),
        eq(memberAbsences.userId, userId),
      ),
    )
    .run();
}

/**
 * Drops this user as anyone's delegate in the workspace. The absence itself
 * stays, so coverage simply stops redirecting.
 */
export async function clearDelegate(
  orgId: OrgId,
  delegateUserId: UserId,
): Promise<void> {
  getDb()
    .update(memberAbsences)
    .set({ delegateUserId: null, updatedAt: toIsoTimestamp(new Date()) })
    .where(
      and(
        orgPredicate(memberAbsences.orgId, orgId),
        eq(memberAbsences.delegateUserId, delegateUserId),
      ),
    )
    .run();
}

