import { emit } from "@/lib/event-bus";
import { assertCan } from "@/lib/permissions";
import { assertOrgScope } from "@/lib/tenant";
import * as absenceRepo from "@/server/repositories/absence-repository";
import * as memberRepo from "@/server/repositories/member-repository";
import { hasRoleAtLeast } from "@/types/member";
import { NotFoundError, actorEnvelope, memberResource, requireFound } from "./_support";
import type {
  ListMembersInput,
  RemoveMemberInput,
  SetAbsenceInput,
  UpdateMemberRoleInput,
} from "@/schemas/member";
import type { MemberId, OrgId, Page, UserId } from "@/types/common";
import type { Actor, Member, MemberAbsence, MemberWithUser, Role } from "@/types/member";

const removed = await memberRepo.archiveMember(input.orgId, input.memberId);

await absenceRepo.deleteAbsence(input.orgId, removed.userId);
await absenceRepo.clearDelegate(input.orgId, removed.userId);

await emit("member.removed", {

  return { userId, orgId, role: member.role };
}

/**
 * Replaces the member's absence in this workspace. The end is exclusive and
 * must fall after the start. A delegate, when named, is another active
 * member of the same workspace.
 */
export async function setAbsence(
  actor: Actor,
  input: SetAbsenceInput,
): Promise<MemberAbsence> {
  assertOrgScope(actor, input.orgId);

  const member = await requireActiveMember(input.orgId, input.userId);
  if (actor.userId !== input.userId) {
    assertCan(actor, "member:update_role", memberResource(member));
  }

  const start = Date.parse(input.startsAt);
  const end = Date.parse(input.endsAt);
  if (!(end > start)) {
    throw new Error("Absence end must be after the start");
  }

  if (input.delegateUserId !== null) {
    if (input.delegateUserId === input.userId) {
      throw new Error("A member cannot be their own delegate");
    }
    await requireActiveMember(input.orgId, input.delegateUserId);
  }

  return absenceRepo.upsertAbsence({
    orgId: input.orgId,
    userId: input.userId,
    delegateUserId: input.delegateUserId,
    startsAt: input.startsAt,
    endsAt: input.endsAt,
    note: input.note,
  });
}

/** Removes the absence. Clearing one that was never set does nothing. */
export async function clearAbsence(
  actor: Actor,
  orgId: OrgId,
  userId: UserId,
): Promise<void> {
  assertOrgScope(actor, orgId);

  const member = await requireActiveMember(orgId, userId);
  if (actor.userId !== userId) {
    assertCan(actor, "member:update_role", memberResource(member));
  }

  await absenceRepo.deleteAbsence(orgId, userId);
}

/**
 * The stored absence while it has not ended, including one that has not
 * started yet. `null` once it has ended or when none is set.
 */
export async function getAbsence(
  actor: Actor,
  orgId: OrgId,
  userId: UserId,
): Promise<MemberAbsence | null> {
  assertOrgScope(actor, orgId);
  assertCan(actor, "member:read", { kind: "organization", orgId });
  await requireActiveMember(orgId, userId);

  const absence = await absenceRepo.findAbsence(orgId, userId);
  if (absence === null || !hasNotEnded(absence, new Date())) return null;
  return absence;
}

/**
 * Assignee written for a new assignment. Self-assignment is never redirected.
 * Delegation is one hop: an away delegate keeps the issue.
 */
export async function resolveDelegatedAssignee(
  orgId: OrgId,
  assigneeId: UserId | null,
  assigningUserId: UserId,
  now: Date = new Date(),
): Promise<UserId | null> {
  if (assigneeId === null || assigneeId === assigningUserId) return assigneeId;
  return (await currentDelegate(orgId, assigneeId, now)) ?? assigneeId;
}

/** Overdue alerts follow the delegate while the assignee is away. */
export async function overdueAlertRecipient(
  orgId: OrgId,
  assigneeId: UserId,
  now: Date,
): Promise<UserId> {
  return (await currentDelegate(orgId, assigneeId, now)) ?? assigneeId;
}

/**
 * Mention alerts still go to each mentioned member, and also to the delegate
 * of anyone who is away. Callers dedupe and apply the author exclusion.
 */
export async function mentionAlertRecipients(
  orgId: OrgId,
  mentionedUserIds: readonly UserId[],
  now: Date,
): Promise<UserId[]> {
  const recipients = [...mentionedUserIds];
  for (const userId of mentionedUserIds) {
    const delegate = await currentDelegate(orgId, userId, now);
    if (delegate !== null) recipients.push(delegate);
  }
  return recipients;
}

/** Active, unarchived member of this workspace, or `NotFoundError`. */
async function requireActiveMember(orgId: OrgId, userId: UserId): Promise<Member> {
  const member = requireFound(
    await memberRepo.findMember(orgId, userId),
    "Member",
    userId,
  );
  if (member.status !== "active") {
    throw new NotFoundError("Member", userId);
  }
  return member;
}

/** Delegate covering `userId` at `now`, when that delegate is still active. */
async function currentDelegate(
  orgId: OrgId,
  userId: UserId,
  now: Date,
): Promise<UserId | null> {
  const absence = await absenceRepo.findAbsence(orgId, userId);
  if (absence === null || !isAway(absence, now) || absence.delegateUserId === null) {
    return null;
  }

