import { emit } from "@/lib/event-bus";
import { PermissionDeniedError } from "@/lib/permissions";
import { TenantScopeError } from "@/lib/tenant";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as notificationRepo from "@/server/repositories/notification-repository";
import * as issueService from "@/server/services/issue-service";
import * as memberService from "@/server/services/member-service";
import { NotFoundError } from "@/server/services/_support";
import { listNotifications } from "@/server/services/notification-service";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { CommentId, OrgId, UserId } from "@/types/common";

let cleanup: () => void;
let tenant: Tenant;
let other: Tenant;

const START = "2026-01-01T00:00:00.000Z";
const END = "2026-12-31T00:00:00.000Z";
const DURING = new Date("2026-06-01T00:00:00.000Z");

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  tenant = await createTenant("absence");
  other = await createTenant("absence-other");
});

afterAll(() => {
  cleanup();
});

async function away(
  userId: UserId,
  delegateUserId: UserId | null,
  window: { startsAt?: string; endsAt?: string } = {},
) {
  return memberService.setAbsence(tenant.actors.owner, {
    orgId: tenant.org.id,
    userId,
    delegateUserId,
    startsAt: (window.startsAt ?? START) as never,
    endsAt: (window.endsAt ?? END) as never,
    note: "ooo",
  });
