import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import { emit } from "@/lib/event-bus";
import { PermissionDeniedError } from "@/lib/permissions";
import { TenantScopeError } from "@/lib/tenant";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as notificationRepo from "@/server/repositories/notification-repository";
import * as issueService from "@/server/services/issue-service";
import * as memberService from "@/server/services/member-service";
import { NotFoundError } from "@/server/services/_support";
import { listNotifications } from "@/server/services/notification-service";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { CommentId, OrgId, UserId } from "@/types/common";

let cleanup: () => void;
let tenant: Tenant;
let other: Tenant;

const START = "2026-01-01T00:00:00.000Z";
const END = "2026-12-31T00:00:00.000Z";
const DURING = new Date("2026-06-01T00:00:00.000Z");

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  tenant = await createTenant("absence");
  other = await createTenant("absence-other");
});

afterAll(() => {
  cleanup();
});

async function away(
  userId: UserId,
  delegateUserId: UserId | null,
  window: { startsAt?: string; endsAt?: string } = {},
) {
  return memberService.setAbsence(tenant.actors.owner, {
    orgId: tenant.org.id,
    userId,
    delegateUserId,
    startsAt: (window.startsAt ?? START) as never,
    endsAt: (window.endsAt ?? END) as never,
    note: "ooo",
  });
}

describe("member absence", () => {
  it("stores, replaces, reads a scheduled window, and clears", async () => {
    const futureStart = "2099-01-01T00:00:00.000Z";
    const futureEnd = "2099-02-01T00:00:00.000Z";
    const stored = await memberService.setAbsence(tenant.actors.member, {
      orgId: tenant.org.id,
      userId: tenant.userIds.member,
      delegateUserId: tenant.userIds.admin,
      startsAt: futureStart as never,
      endsAt: futureEnd as never,
      note: "later",
    });
    expect(stored).toMatchObject({
      orgId: tenant.org.id,
      userId: tenant.userIds.member,
      delegateUserId: tenant.userIds.admin,
      startsAt: futureStart,
      endsAt: futureEnd,
      note: "later",
    });

    const read = await memberService.getAbsence(
      tenant.actors.viewer,
      tenant.org.id,
      tenant.userIds.member,
    );
    expect(read).toEqual(stored);

    const replaced = await memberService.setAbsence(tenant.actors.member, {
      orgId: tenant.org.id,
      userId: tenant.userIds.member,
      delegateUserId: null,
      startsAt: futureStart as never,
      endsAt: futureEnd as never,
      note: null,
    });
    expect(replaced.delegateUserId).toBeNull();
    expect(replaced.note).toBeNull();

    await memberService.clearAbsence(
      tenant.actors.member,
      tenant.org.id,
      tenant.userIds.member,
    );
    await memberService.clearAbsence(
      tenant.actors.member,
      tenant.org.id,
      tenant.userIds.member,
    );
    expect(
      await memberService.getAbsence(
        tenant.actors.member,
        tenant.org.id,
        tenant.userIds.member,
      ),
    ).toBeNull();
  });

  it("rejects a window that does not move forward and a self delegate", async () => {
    await expect(
      memberService.setAbsence(tenant.actors.member, {
        orgId: tenant.org.id,
        userId: tenant.userIds.member,
        delegateUserId: null,
        startsAt: END as never,
        endsAt: START as never,
        note: null,
      }),
    ).rejects.toThrow(/after the start/);

    await expect(
      memberService.setAbsence(tenant.actors.member, {
        orgId: tenant.org.id,
        userId: tenant.userIds.member,
        delegateUserId: tenant.userIds.member,
        startsAt: START as never,
        endsAt: END as never,
        note: null,
      }),
    ).rejects.toThrow(/own delegate/);
  });

  it("hides an ended absence and refuses unknown members", async () => {
    await away(tenant.userIds.admin, tenant.userIds.owner, {
      startsAt: "2020-01-01T00:00:00.000Z",
      endsAt: "2020-02-01T00:00:00.000Z",
    });
    expect(
      await memberService.getAbsence(
        tenant.actors.owner,
        tenant.org.id,
        tenant.userIds.admin,
      ),
    ).toBeNull();

    await expect(
      memberService.getAbsence(
        tenant.actors.owner,
        tenant.org.id,
        "01HZZZNOBODYNOBODYNOBODY00" as UserId,
      ),
    ).rejects.toBeInstanceOf(NotFoundError);

    await expect(
      memberService.setAbsence(tenant.actors.owner, {
        orgId: tenant.org.id,
        userId: tenant.userIds.member,
        delegateUserId: other.userIds.member,
        startsAt: START as never,
        endsAt: END as never,
        note: null,
      }),
    ).rejects.toBeInstanceOf(NotFoundError);
  });

  it("scopes every operation and limits who may edit someone else", async () => {
    await expect(
      memberService.setAbsence(tenant.actors.member, {
        orgId: other.org.id,
        userId: other.userIds.member,
        delegateUserId: null,
        startsAt: START as never,
        endsAt: END as never,
        note: null,
      }),
    ).rejects.toBeInstanceOf(TenantScopeError);

    await expect(
      memberService.getAbsence(tenant.actors.owner, other.org.id, other.userIds.member),
    ).rejects.toBeInstanceOf(TenantScopeError);

    await expect(
      memberService.clearAbsence(tenant.actors.owner, other.org.id, other.userIds.owner),
    ).rejects.toBeInstanceOf(TenantScopeError);

    await expect(
      memberService.setAbsence(tenant.actors.member, {
        orgId: tenant.org.id,
        userId: tenant.userIds.admin,
        delegateUserId: null,
        startsAt: START as never,
        endsAt: END as never,
        note: null,
      }),
    ).rejects.toBeInstanceOf(PermissionDeniedError);

    const set = await memberService.setAbsence(tenant.actors.admin, {
      orgId: tenant.org.id,
      userId: tenant.userIds.viewer,
      delegateUserId: tenant.userIds.member,
      startsAt: START as never,
      endsAt: END as never,
      note: null,
    });
    expect(set.userId).toBe(tenant.userIds.viewer);
    await memberService.clearAbsence(
      tenant.actors.owner,
      tenant.org.id,
      tenant.userIds.viewer,
    );
  });

  it("redirects create and assign once, but not a self-assign", async () => {
    vi.useFakeTimers();
    vi.setSystemTime(DURING);
    try {
      await away(tenant.userIds.admin, tenant.userIds.viewer);
      await away(tenant.userIds.viewer, tenant.userIds.owner);

      const created = await issueService.createIssue(
        tenant.actors.member,
        issueInput(tenant.org.id, tenant.project.id, {
          title: "Delegated create",
          assigneeId: tenant.userIds.admin,
        }),
      );
      expect(created.assigneeId).toBe(tenant.userIds.viewer);

      const self = await issueService.createIssue(
        tenant.actors.admin,
        issueInput(tenant.org.id, tenant.project.id, {
          title: "Self create",
          assigneeId: tenant.userIds.admin,
        }),
      );
      expect(self.assigneeId).toBe(tenant.userIds.admin);

      const issue = await issueService.createIssue(
        tenant.actors.member,
        issueInput(tenant.org.id, tenant.project.id, { title: "Assign later" }),
      );
      const assigned = await issueService.assignIssue(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: issue.id,
        assigneeId: tenant.userIds.admin,
      });
      expect(assigned.assigneeId).toBe(tenant.userIds.viewer);

      const taken = await issueService.assignIssue(tenant.actors.admin, {
        orgId: tenant.org.id,
        issueId: issue.id,
        assigneeId: tenant.userIds.admin,
      });
      expect(taken.assigneeId).toBe(tenant.userIds.admin);
    } finally {
      vi.useRealTimers();
      await memberService.clearAbsence(
        tenant.actors.owner,
        tenant.org.id,
        tenant.userIds.admin,
      );
      await memberService.clearAbsence(
        tenant.actors.owner,
        tenant.org.id,
        tenant.userIds.viewer,
      );
    }
  });

  it("drops an absence with its member and clears a removed delegate", async () => {
    vi.useFakeTimers();
    vi.setSystemTime(DURING);
    try {
      await away(tenant.userIds.member, tenant.userIds.admin);
      const adminMember = await (
        await import("@/server/repositories/member-repository")
      ).findMember(tenant.org.id, tenant.userIds.admin);
      if (!adminMember) throw new Error("missing");

      await memberService.removeMember(tenant.actors.owner, {
        orgId: tenant.org.id,
        memberId: adminMember.id,
      });

      const issue = await issueService.createIssue(
        tenant.actors.owner,
        issueInput(tenant.org.id, tenant.project.id, {
          title: "Delegate left",
          assigneeId: tenant.userIds.member,
        }),
      );
      expect(issue.assigneeId).toBe(tenant.userIds.member);

      const memberRow = await (
        await import("@/server/repositories/member-repository")
      ).findMember(tenant.org.id, tenant.userIds.member);
      if (!memberRow) throw new Error("missing member");
      await memberService.removeMember(tenant.actors.owner, {
        orgId: tenant.org.id,
        memberId: memberRow.id,
      });
      await expect(
        memberService.getAbsence(
          tenant.actors.owner,
          tenant.org.id,
          tenant.userIds.member,
        ),
      ).rejects.toBeInstanceOf(NotFoundError);
    } finally {
      vi.useRealTimers();
    }
  });

  it("sends overdue alerts and mention alerts to the delegate", async () => {
    vi.useFakeTimers();
    vi.setSystemTime(DURING);
    try {
      await away(tenant.userIds.owner, tenant.userIds.admin);

      const issue = await issueRepo.insertIssue(
        issueInput(tenant.org.id, tenant.project.id, {
          title: "Overdue mine",
          assigneeId: tenant.userIds.owner,
          dueAt: "2026-01-02T00:00:00.000Z",
        }),
        tenant.userIds.member,
        await issueRepo.nextIssueNumber(tenant.org.id, tenant.project.id),
      );

      await emit("issue.overdue", {
        orgId: tenant.org.id,
        actorId: null,
        occurredAt: DURING.toISOString() as never,
        issueId: issue.id,
        projectId: issue.projectId,
        dueAt: issue.dueAt!,
        assigneeId: tenant.userIds.owner,
      });

      const overdueForOwner = await listNotifications(tenant.actors.owner, {
        orgId: tenant.org.id,
        recipientId: tenant.userIds.owner,
        unreadOnly: false,
        kind: ["issue_overdue"],
        limit: 25,
        cursor: null,
      });
      const overdueForAdmin = await listNotifications(tenant.actors.owner, {
        orgId: tenant.org.id,
        recipientId: tenant.userIds.admin,
        unreadOnly: false,
        kind: ["issue_overdue"],
        limit: 25,
        cursor: null,
      });
      expect(overdueForOwner.items).toHaveLength(0);
      expect(overdueForAdmin.items).toHaveLength(1);

      await emit("comment.created", {
        orgId: tenant.org.id,
        actorId: tenant.userIds.member,
        occurredAt: DURING.toISOString() as never,
        commentId: "01HZZZCOMMENTCOMMENTCOMMENT" as CommentId,
        issueId: issue.id,
        mentionedUserIds: [tenant.userIds.owner, tenant.userIds.admin],
      });

      const mentionsOwner = await listNotifications(tenant.actors.owner, {
        orgId: tenant.org.id,
        recipientId: tenant.userIds.owner,
        unreadOnly: false,
        kind: ["comment_mention"],
        limit: 25,
        cursor: null,
      });
      const mentionsAdmin = await listNotifications(tenant.actors.owner, {
        orgId: tenant.org.id,
        recipientId: tenant.userIds.admin,
        unreadOnly: false,
        kind: ["comment_mention"],
        limit: 25,
        cursor: null,
      });
      expect(mentionsOwner.items).toHaveLength(1);
      expect(mentionsAdmin.items).toHaveLength(1);

      void notificationRepo;
      void other;
    } finally {
      vi.useRealTimers();
    }
  });
});

